const rawInput = $input.first().json;
const body = rawInput.body ? rawInput.body : rawInput;

if (!body.request_id) {
  return [{ json: { decision: 'REJECTED', reason: 'MISSING_REQUEST_ID', message: 'request_id is required.' } }];
}
if (body.action !== 'create' && body.action !== 'verify_and_attach') {
  return [{ json: { decision: 'REJECTED', reason: 'INVALID_ACTION', message: 'action must be "create" or "verify_and_attach".' } }];
}

return [{ json: { decision: 'VALID', request_id: body.request_id, action: body.action } }];

// approval_logs.approval_status is set once, at approval time, and
// never changes afterward - it's a record of that event, not a live
// status. So this check passes the same way for "create" and for
// "verify_and_attach" on an already-attempted request; what actually
// gates a fresh attempt is the atomic claim below, not this.
const validated = $('Validate Input').first().json;

const approvalRaw = $('Fetch Approval Log').first().json;
const approvalRow = Array.isArray(approvalRaw) ? approvalRaw[0] : approvalRaw;

const mergeRaw = $('Fetch Merge Request').first().json;
const mergeRow = Array.isArray(mergeRaw) ? mergeRaw[0] : mergeRaw;

if (!approvalRow || approvalRow.approval_status !== 'approved' || !approvalRow.staged_payload_json) {
  return [{ json: { decision: 'REJECTED', reason: 'NOT_APPROVED', request_id: validated.request_id,
    message: 'No approved, staged payload found for this request_id.' } }];
}

if (!mergeRow) {
  return [{ json: { decision: 'REJECTED', reason: 'MERGE_REQUEST_NOT_FOUND', request_id: validated.request_id,
    message: 'No merge_requests row found for this request_id.' } }];
}

if (!mergeRow.is_new_parent) {
  return [{ json: { decision: 'REJECTED', reason: 'WRONG_MODE', request_id: validated.request_id,
    message: 'This is an existing-parent merge - this workflow only handles new-parent merges. Use wf32 instead.' } }];
}

if (!mergeRow.new_parent_sku) {
  return [{ json: { decision: 'REJECTED', reason: 'NO_PARENT_SKU', request_id: validated.request_id,
    message: 'This merge_requests row has no new_parent_sku set.' } }];
}

return [{ json: {
  decision: 'READY',
  action: validated.action,
  request_id: validated.request_id,
  seller_id: mergeRow.seller_id,
  marketplace_id: mergeRow.marketplace_id,
  new_parent_sku: mergeRow.new_parent_sku,
  messages: approvalRow.staged_payload_json.messages || []
}}];

const ready = $('Check Ready To Submit').first().json;
const upstream = $input.first().json;
const rows = Array.isArray(upstream) ? upstream : (upstream && upstream.request_id ? [upstream] : []);

if (rows.length === 0) {
  return [{ json: { decision: 'REJECTED', reason: 'CLAIM_LOST', request_id: ready.request_id,
    message: 'Could not claim this submission - it may already be in progress or completed. If you meant to check on an already-attempted request, use action=verify_and_attach instead, which does not need to claim anything.' } }];
}

return [{ json: {
  decision: 'CLAIMED',
  action: ready.action,
  request_id: ready.request_id,
  seller_id: ready.seller_id,
  marketplace_id: ready.marketplace_id,
  new_parent_sku: ready.new_parent_sku,
  messages: ready.messages
}}];

const ready = $('Check Ready To Submit').first().json;
return [{ json: {
  decision: 'CLAIMED',
  action: ready.action,
  request_id: ready.request_id,
  seller_id: ready.seller_id,
  marketplace_id: ready.marketplace_id,
  new_parent_sku: ready.new_parent_sku,
  messages: ready.messages
}}];

const context = $('Resolve Submission Context').first().json;
const sellingPartnerRaw = $('Get Seller Selling Partner ID').first().json;
const sellingPartnerRow = Array.isArray(sellingPartnerRaw) ? sellingPartnerRaw[0] : sellingPartnerRaw;
const sellingPartnerId = sellingPartnerRow && sellingPartnerRow.selling_partner_id;
const accessToken = $('Exchange for Access Token').first().json.access_token;

if (!sellingPartnerId || !accessToken) {
  return [{ json: {
    decision: 'REJECTED', reason: 'MISSING_CREDENTIALS', request_id: context.request_id,
    message: 'Could not resolve a selling_partner_id or access_token - refusing to attempt any real calls without both.'
  }}];
}

const parentMessage = context.messages.find(function(m) { return m.sku === context.new_parent_sku; });
const childMessages = context.messages.filter(function(m) { return m.sku !== context.new_parent_sku; });

if (!parentMessage) {
  return [{ json: {
    decision: 'REJECTED', reason: 'PARENT_MESSAGE_NOT_FOUND', request_id: context.request_id,
    message: 'No message for the parent sku "' + context.new_parent_sku + '" found in the staged payload.'
  }}];
}

const parentResult = { sku: parentMessage.sku, patch_status: null, patch_issues: [], verified_parent: false, verify_issues: [], verify_attempts: 0, error: null };

// A verify call that throws isn't necessarily a real failure - a 404
// right after creating a listing is Amazon's own catalog/search index
// not having caught up yet, the exact same delay the retry schedules
// below already exist to wait out (see the comment on delaysMs). Live
// evidence: Parent_YY50's verify_and_attach threw a 404 on its very
// first check and the whole call ended there, using 1 of 6 available
// attempts instead of retrying like a clean verified:false would have.
// Only a genuinely non-retryable status should actually stop early.
function isRetryableStatus(err) {
  let status = null;
  if (err && err.response && typeof err.response.status === 'number') status = err.response.status;
  else if (err && err.response && typeof err.response.statusCode === 'number') status = err.response.statusCode;
  else if (err && typeof err.statusCode === 'number') status = err.statusCode;
  else {
    // Last resort: axios's own default error message embeds the code -
    // e.g. "Request failed with status code 404", the exact message
    // seen on Parent_YY50's real failure.
    const match = /status code (\d{3})/i.exec((err && err.message) || '');
    if (match) status = parseInt(match[1], 10);
  }
  if (status === 404) return true;
  if (status >= 500 && status < 600) return true;
  if (!status) return true; // network error / timeout / no response at all - worth another try
  return false;
}

if (context.action === 'create') {
  // putListingsItem needs a flat attributes object, not the patches
  // array patchListingsItem uses - same conversion wf33 proved.
  const parentAttributes = {};
  for (const patch of parentMessage.patches) {
    const attrName = patch.path.replace('/attributes/', '');
    parentAttributes[attrName] = patch.value;
  }
  try {
    const putResponse = await this.helpers.httpRequest({
      method: 'PUT',
      url: 'https://sellingpartnerapi-na.amazon.com/listings/2021-08-01/items/' + sellingPartnerId + '/' + encodeURIComponent(parentMessage.sku),
      qs: { marketplaceIds: context.marketplace_id, issueLocale: 'en_US' },
      headers: { 'Content-Type': 'application/json', 'x-amz-access-token': accessToken },
      body: { productType: parentMessage.productType, requirements: 'LISTING', attributes: parentAttributes },
      json: true
    });
    parentResult.patch_status = putResponse.status || null;
    parentResult.patch_issues = putResponse.issues || [];
  } catch (err) {
    parentResult.error = 'parent create call failed: ' + (err.message || String(err));
  }
}
// For verify_and_attach, the real PUT already happened in an earlier
// create call - skip straight to checking what's actually true now.

async function checkParentState() {
  const stateResponse = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://sellingpartnerapi-na.amazon.com/listings/2021-08-01/items/' + sellingPartnerId + '/' + encodeURIComponent(parentMessage.sku),
    qs: { marketplaceIds: context.marketplace_id, includedData: 'summaries,attributes,issues' },
    headers: { 'x-amz-access-token': accessToken },
    json: true
  });
  const attrs = stateResponse.attributes || {};
  const hasAsin = Array.isArray(stateResponse.summaries) && stateResponse.summaries.length > 0 && !!stateResponse.summaries[0].asin;
  const parentageEntry = attrs.parentage_level && attrs.parentage_level[0];
  return { verified: hasAsin && !!parentageEntry && parentageEntry.value === 'parent', issues: stateResponse.issues || [] };
}

if (!parentResult.error) {
  // "create" gets a short check - Parent_AJ75 confirmed within this
  // kind of window before. "verify_and_attach" gets a genuinely longer
  // one, since its whole purpose is giving Amazon's own processing more
  // time - proven necessary today: Parent_SR12 wasn't confirmed within
  // create's short window, but was real and confirmed a few minutes
  // later. Still not an unlimited wait - if even this isn't enough,
  // verify_and_attach is safe to call again, since it never repeats
  // the actual write.
  const delaysMs = context.action === 'create'
    ? [3000, 5000, 8000]
    : [5000, 10000, 15000, 20000, 30000];

  for (let i = 0; i <= delaysMs.length; i++) {
    if (i > 0) {
      await new Promise(function(resolve) { setTimeout(resolve, delaysMs[i - 1]); });
    }
    parentResult.verify_attempts++;
    try {
      const state = await checkParentState.call(this);
      parentResult.verified_parent = state.verified;
      parentResult.verify_issues = state.issues;
      if (parentResult.verified_parent) {
        parentResult.error = null; // clear any earlier transient error - this attempt succeeded
        break;
      }
    } catch (err) {
      const message = 'parent verify call failed: ' + (err.message || String(err));
      parentResult.error = message;
      if (isRetryableStatus(err) && i < delaysMs.length) {
        continue; // treat like a clean verified:false - the schedule still has rounds left
      }
      break;
    }
  }
}

const results = [parentResult];

if (parentResult.verified_parent) {
  for (const msg of childMessages) {
    const entry = { sku: msg.sku, patch_status: null, patch_issues: [], verified_child: false, verify_issues: [], verify_attempts: 0, error: null };
    try {
      const patchResponse = await this.helpers.httpRequest({
        method: 'PATCH',
        url: 'https://sellingpartnerapi-na.amazon.com/listings/2021-08-01/items/' + sellingPartnerId + '/' + encodeURIComponent(msg.sku),
        qs: { marketplaceIds: context.marketplace_id, issueLocale: 'en_US' },
        headers: { 'Content-Type': 'application/json', 'x-amz-access-token': accessToken },
        body: { productType: msg.productType, patches: msg.patches },
        json: true
      });
      entry.patch_status = patchResponse.status || null;
      entry.patch_issues = patchResponse.issues || [];
    } catch (err) {
      entry.error = 'patch call failed: ' + (err.message || String(err));
    }
    results.push(entry);
  }

  // Extended to match the parent's own window - real evidence today
  // suggests a genuinely new family may need as much time to settle as
  // the parent creation itself did, not the shorter window a simple
  // attribute patch to an already-established family needed.
  const childVerifyDelaysMs = [5000, 10000, 15000, 20000, 30000];
  for (let attempt = 0; attempt <= childVerifyDelaysMs.length; attempt++) {
    if (attempt > 0) {
      await new Promise(function(resolve) { setTimeout(resolve, childVerifyDelaysMs[attempt - 1]); });
    }
    const stillPending = results.slice(1).filter(function(r) { return !r.verified_child && !r.error; });
    if (stillPending.length === 0) break;
    for (const entry of stillPending) {
      entry.verify_attempts++;
      try {
        const stateResponse = await this.helpers.httpRequest({
          method: 'GET',
          url: 'https://sellingpartnerapi-na.amazon.com/listings/2021-08-01/items/' + sellingPartnerId + '/' + encodeURIComponent(entry.sku),
          qs: { marketplaceIds: context.marketplace_id, includedData: 'attributes,issues' },
          headers: { 'x-amz-access-token': accessToken },
          json: true
        });
        const attrs = stateResponse.attributes || {};
        entry.verified_child = !!(attrs.parentage_level && attrs.parentage_level.some(function(e) { return e.value === 'child'; }));
        entry.verify_issues = stateResponse.issues || [];
      } catch (err) {
        const message = 'verify call failed: ' + (err.message || String(err));
        // stillPending's own filter above only excludes entries with
        // entry.error set - recording a retryable failure here instead
        // keeps this entry in the rotation for the remaining rounds,
        // rather than silently dropping it after one bad response.
        if (isRetryableStatus(err)) {
          entry.last_verify_error = message;
        } else {
          entry.error = message;
        }
      }
    }
  }
} else {
  const skipReason = context.action === 'create'
    ? 'skipped - parent not yet confirmed; call verify_and_attach to keep checking and attach children once it is'
    : 'skipped - parent still not confirmed after this check; safe to call verify_and_attach again';
  for (const msg of childMessages) {
    results.push({ sku: msg.sku, patch_status: null, patch_issues: [], verified_child: false, verify_issues: [], verify_attempts: 0, error: skipReason });
  }
}

return [{ json: {
  decision: 'SUBMITTED',
  action: context.action,
  request_id: context.request_id,
  parent_still_pending: !parentResult.verified_parent && !parentResult.error,
  results: results
}}];

const submitted = $input.first().json;
const results = submitted.results || [];
const parentResult = results[0];
const childResults = results.slice(1);

const parentOk = !!(parentResult && parentResult.verified_parent);
const allChildrenOk = childResults.length > 0 && childResults.every(function(r) { return r.verified_child; });
const noChildrenOk = childResults.length === 0 || childResults.every(function(r) { return !r.verified_child; });

let finalStatus;
if (submitted.parent_still_pending) {
  // Not a failure - genuinely still processing. Left as 'submitting' so
  // a later verify_and_attach call can still pick this request up; a
  // status of 'failed' would incorrectly block that via the atomic claim.
  finalStatus = 'submitting';
} else if (!parentOk) {
  finalStatus = 'failed';
} else if (allChildrenOk) {
  finalStatus = 'verified';
} else if (noChildrenOk) {
  finalStatus = 'failed';
} else {
  finalStatus = 'partially_failed';
}

return [{ json: {
  decision: 'SUMMARIZED',
  request_id: submitted.request_id,
  final_status: finalStatus,
  parent_verified: parentOk,
  parent_still_pending: !!submitted.parent_still_pending,
  child_count: childResults.length,
  verified_child_count: childResults.filter(function(r) { return r.verified_child; }).length,
  results: results
}}];
